def f(*,x): return x
class K:
 def __hash__(self): return hash("x")
 def __eq__(self,other):
  print("equal")
  return other=="x"
k=K()
d={k:[7]}
f.__kwdefaults__=d
print(f()[0])
d[k]=[9]
print(f()[0])

def f(a,*,x): return a,x
class K:
 def __hash__(self): return hash("x")
 def __eq__(self,other):
  print("callback")
  raise ValueError("stop")
f.__kwdefaults__={K():7}
try: f()
except TypeError: print("positional")
f(1)

__builtins__={"len":lambda value: 17}
def f(value): return len(value)
d=f.__builtins__
__builtins__={"len":lambda value: 19}
def g(value): return len(value)
print(f([]),g([]),f.__builtins__ is d,g.__builtins__ is __builtins__)
d["len"]=lambda value: 23
print(f([]))

__builtins__={}
def f(): return len([])
f()

class K:
 def __hash__(self): return hash("len")
 def __eq__(self,other):
  print("equal")
  return other=="len"
d={K():lambda value: 27}
__builtins__=d
def f(): return len([])
print(f(),f.__builtins__ is d)
